// Vistas visuales del editor; no calculan ni guardan estrategias.
function editorFooter(extra='') {
  return `<footer class="journey-editor-footer"><span>${detailIcon('info')}Los archivos de telemetría originales nunca se sobrescriben.</span><div>${extra}${previewButton('Volver al plan','plan')}<button class="orbit-btn orbit-btn--primary" disabled>${journeyIcon(state.view==='advanced'?'refresh':'save')}<span>${state.view==='advanced'?'Aplicar y recalcular':'Guardar revisión'}</span></button></div></footer>`;
}
function editorHeading(title,intro) {
  return `<header class="journey-editor-heading"><h2 tabindex="-1">${title}</h2><p>${intro}</p></header>`;
}
function summaryScreen(source) {
  const item=(glyph,label,value,sub,action)=>`<div class="race-review-row">${journeyIcon(glyph)}<span>${label}</span><div><strong>${value}</strong><small>${sub}</small></div><button class="orbit-btn orbit-btn--ghost" data-action="${action}">${journeyIcon('edit')}Editar</button></div>`;
  return `<div class="race-summary-grid"><div class="stack">${item('calendar','Evento','Carrera personalizada',source.track,'event')}${item('wrench','Reglas',state.duration?`${esc(state.duration)} ${esc(state.unit)}`:'Por confirmar',esc(state.weather),'rules')}${item('group','Pilotos',esc(state.driver||'Por confirmar'),'Ritmo pendiente de validar','pilots')}<section class="wizard-card summary-source"><span class="eyebrow">FUENTE DE DATOS</span><div class="summary-source-row">${circuitOutline()}<div><strong>${source.track} · ${source.date}</strong><p>${source.laps} vueltas registradas</p></div>${previewButton('Revisar','advanced')}</div><hr><span class="eyebrow">OBSERVACIONES</span><div class="summary-source-row">${detailIcon('document')}<div><strong>Pendiente de validar</strong><p>Revisa las reglas y la telemetría antes de calcular.</p></div>${previewButton('Ver detalles','advanced')}</div></section></div><section class="wizard-card summary-result"><h3>${journeyIcon('flag')}Plan de carrera</h3><div><div><h3>Sin calcular</h3><p>Completa las reglas y revisa la telemetría para calcular la estrategia.</p></div>${button('Calcular estrategia','',true,true)}</div><small>El cálculo y el guardado aún no están conectados.</small></section></div>`;
}
const dataFamilies=[['pace','gauge','Ritmo','Ritmo representativo'],['fuel','fuel','Fuel','Consumo por vuelta'],['energy','energy','Energía virtual','Consumo de energía virtual'],['tyres','tyre','Neumáticos','Desgaste'],['pit','boxes','Boxes','Parada completa observada']];
function dataScreen(source) {
  const current=dataFamilies.find(f=>f[0]===(state.family||'pace')) || dataFamilies[0];
  const value=current[0]==='pit'?source.pit:'Pendiente de validar';
  return `<div class="data-review-grid"><section class="panel observation-list"><div class="family-tabs" role="group" aria-label="Familias de datos">${dataFamilies.map(([id,glyph,label])=>`<button data-family="${id}" aria-pressed="${id===current[0]}">${journeyIcon(glyph)}${label}</button>`).join('')}</div><div class="observation-heading"><h3>Observaciones de la sesión</h3><p>Revisa cada dato registrado. Las correcciones conservarán el archivo original.</p></div><div class="observation-table"><div class="observation-columns"><span>Dato</span><span>Original</span><span>Corrección</span><span>Uso</span></div>${dataFamilies.filter(f=>f[0]===current[0]||['pace','fuel','tyres'].includes(f[0])).map(([id,glyph,label,name])=>`<button data-family="${id}" class="observation-row" aria-pressed="${id===current[0]}"><span>${detailIcon(glyph)}${name}</span><span>${id==='pit'?source.pit:'Pendiente de validar'}</span><span>Sin cambios</span><span class="review-state">${journeyIcon('warning')}Revisar<b>›</b></span></button>`).join('')}</div><details class="observed-evidence"><summary>Ver observaciones del banco</summary><p>Entrada: ${source.entry} s · Salida: ${source.exit} s · Fuel añadido: ${source.fuel}.</p><p>${source.record}. Los incidentes y las vueltas invalidadas aún no están adjudicados.</p><p>Contraste exploratorio #1030; no certifica el modelo de carrera.</p></details></section><section class="panel observation-inspector"><h3>Revisar observación</h3><p>${source.track} · sesión registrada</p><h4>${detailIcon(current[1])}${current[3]}</h4><label>Original (solo lectura)<div class="locked-input"><input value="${value}" readonly>${journeyIcon('lock')}</div></label><label>Valor corregido<select disabled><option>Sin cambios</option></select></label><label>Motivo del cambio<textarea placeholder="Explica brevemente el motivo de esta corrección…" maxlength="500" disabled></textarea></label><span class="counter">0/500</span><span>Uso de la sesión en la estrategia</span><div class="usage-choice"><button data-action="toggle-source" ${state.include?'disabled':''} aria-pressed="${state.include}"><i>${state.include?'●':'○'}</i><span>Incluir<small>Utilizar esta sesión</small></span></button><button data-action="toggle-source" ${!state.include?'disabled':''} aria-pressed="${!state.include}"><i>${!state.include?'●':'○'}</i><span>Excluir<small>No utilizar esta sesión</small></span></button></div>${button('Aplicar corrección','',true,true)}<p class="journey-note">ⓘ Una vuelta invalidada puede utilizarse si es representativa.</p><div id="announce" role="status" aria-live="polite"></div></section></div>`;
}
function emptyPlan() {
  const reason=(glyph,title)=>`<details class="plan-reason" open><summary>${journeyIcon(glyph)}${title}</summary><p>Disponible tras calcular.</p></details>`;
  return `<div class="plan-metrics">${[['clock','Tiempo previsto'],['wrench','Paradas'],['fuel','Fuel inicial'],['energy','Energía virtual'],['flag','Margen de llegada']].map(([glyph,label])=>`<div class="detail-metric">${journeyIcon(glyph)}<div><span>${label}</span><strong>—</strong></div></div>`).join('')}</div><div class="plan-overview-grid"><div class="stack">${detailPanel('Desarrollo de la carrera','<div class="race-empty-track"><div><span>Salida</span><span>Llegada</span></div><p>Stints y paradas según el cálculo</p><div class="empty-track-line"><i></i><i class="finish-flag"></i></div></div>','Esquema de presentación · sin resultado calculado')}${detailPanel('Detalle del plan','<div class="plan-table-head"><span>Stint</span><span>Piloto</span><span>Vueltas</span><span>Fuel / VE</span><span>Neumáticos</span><span>Servicio</span></div><div class="plan-table-empty">'+detailIcon('document')+'<p>El motor completará esta tabla<br>después de calcular la estrategia.</p></div><div class="detail-preview-links">'+previewButton('Ver diseño del stint','stint')+previewButton('Ver diseño de parada','pit')+'</div>','El detalle por stint se mostrará tras calcular la estrategia.')}</div>${detailPanel('Por qué este plan','<p>La justificación se mostrará tras calcular la estrategia.</p>'+reason('target','Objetivo')+reason('shield','Restricciones comprobadas')+reason('document','Supuestos y límites')+'<p class="journey-note">ⓘ Factibilidad y optimalidad se informan por separado.</p>')}</div>`;
}
function calculationScreen() {
  const stages=[['Comprobar datos y reglas','Verificar la integridad de los datos, reglas del evento y configuración del entorno.'],['Evaluar planes factibles','Evaluar las opciones de estrategia según el contexto de la carrera.'],['Seleccionar el mejor plan','Comparar los resultados según los criterios definidos.'],['Verificar la carrera completa','Validar el plan seleccionado con comprobaciones finales.']];
  return `<div class="calculation-grid"><section class="panel process-panel"><h3>Progreso del cálculo</h3><p class="process-status">Preparado para conectar · Sin cálculo en ejecución</p><ol>${stages.map(([title,text],i)=>`<li><span>${i+1}</span><div><h3>${title}</h3><p>${text}</p></div></li>`).join('')}</ol><div class="process-actions">${button('Cancelar','',false,true)}${previewButton('Volver al plan','plan')}</div></section><div class="stack">${detailPanel('Este cálculo utilizará',[['flag','Evento y reglas','Configuración del evento','summary'],['target','Sesiones seleccionadas','Observaciones y condiciones','advanced'],['sliders','Correcciones aplicadas','Ajustes de los datos','advanced'],['helmet','Estimaciones de pilotos','Ritmo y procedencia','summary']].map(([glyph,title,text,view])=>`<button class="calculation-input" data-view="${view}">${glyph==='target'?circuitOutline():journeyIcon(glyph)}<span><strong>${title}</strong><small>${text}</small></span><b>›</b></button>`).join(''))}${detailPanel(journeyIcon('shield')+'Sin incidentes imprevistos','<p>Este cálculo asumirá una carrera sin Safety Car, banderas rojas o interrupciones no planificadas.</p><hr><p class="energy-safeguard">' + journeyIcon('energy') + ' Fuel y energía virtual se comprobarán por separado.</p>')}<section class="wizard-card calculation-previous">${journeyIcon('info')}<p>La revisión anterior permanecerá disponible durante el cálculo.</p><button class="orbit-btn orbit-btn--ghost" data-view="revisions">${journeyIcon('history')}Ver revisiones</button></section></div></div>`;
}
function revisionsScreen() {
  return `<div class="revisions-grid"><section class="panel revisions-empty">${journeyIcon('file')}<h3>Todavía no hay revisiones guardadas</h3><p>Cada revisión conservará datos, reglas y resultado.</p></section>${detailPanel('¿Qué se guarda en cada revisión?',[['document','Datos y correcciones','Fuentes utilizadas y cambios realizados.'],['gear','Reglas del evento','Configuración y restricciones aplicadas.'],['bars','Resultado y versión del motor','Estrategia generada y versión del motor utilizada.']].map(([glyph,title,text])=>`<div class="revision-info">${journeyIcon(glyph)}<div><strong>${title}</strong><p>${text}</p></div></div>`).join(''))}</div>`;
}
function editorScreen() {
  const source=sources[state.combo];
  const pages={summary:['Tu estrategia · '+source.track,'Revisa la configuración de tu carrera y prepara la estrategia.',()=>summaryScreen(source)],advanced:['Revisa los datos de tu carrera','Comprueba la información registrada y define qué datos se utilizarán en tu estrategia.',()=>dataScreen(source)],plan:['Tu plan de carrera','Revisa el esquema de tu estrategia. Ajusta los datos y recalcula para explorar diferentes escenarios.',emptyPlan],calculation:['Cálculo de tu estrategia','De los datos revisados a un plan de carrera verificable.',calculationScreen],revisions:['Revisiones de tu estrategia','Conserva los datos y decisiones de cada versión de tu plan.',revisionsScreen]};
  const [title,intro,body]=pages[state.view];
  const extra=state.view==='advanced'?button('Deshacer','undo',false,state.undo===null):state.view==='plan'?previewButton('Ver proceso de cálculo','calculation'):state.view==='summary'?button('Volver a preparación','sources'):'';
  return `<div class="page plan-page journey-editor view-${state.view}">${planTabs(state.view)}${editorHeading(title,intro)}${state.view==='advanced'?`<button class="orbit-btn orbit-btn--ghost heading-edit" data-action="rules">${journeyIcon('gear')}<span>Editar reglas<small>Condiciones de carrera</small></span></button>`:''}${body()}${state.view==='calculation'?'':editorFooter(extra)}</div>`;
}
